// Decode and sample unit-emission fields (format aqsim-fields v2). No DOM access.
//
// A line-by-line port of export/_loadtest/aqfields.js, which mirrors aqsim/fields/interp.py
// (log-trilinear interpolation, polar and road-aligned frames, mirror option). Two changes,
// neither of which alters a result: the bracketing helpers write into module-level scratch
// variables instead of returning arrays (no allocation per sample), and the prepared value
// arrays are Float32 (the decoded values are float32, so this is lossless; logs stay Float64).
import type { FieldEntry, GridSpec, Manifest } from "./manifest";

export interface PolarField {
  frame: "polar";
  nz: number; nr: number; np: number; npe: number;
  r: Float64Array; logr: Float64Array; phiExt: Float64Array; z: Float64Array;
  v: Float32Array; lv: Float64Array; ring0: Float64Array;
}
export interface RoadField {
  frame: "road";
  nz: number; ns: number; nd: number;
  s: Float64Array; d: Float64Array; z: Float64Array;
  v: Float32Array; lv: Float64Array; orientation: number;
}
export type PreparedField = PolarField | RoadField;

/** Decode one tile into a Float32Array of C values (µg/m³ per g/s) in the grid's C order. */
export function decodeTile(buf: ArrayBuffer, manifest: Pick<Manifest, "encoding" | "grids">, entry: Pick<FieldEntry, "frame" | "file" | "log10_min" | "log10_step" | "scale">): Float32Array {
  const enc = manifest.encoding.name;
  const shape = manifest.grids[entry.frame].shape;
  const n = shape[0] * shape[1] * shape[2];
  return decodeCodes(buf, enc, n, entry.log10_min, entry.log10_step, entry.file, entry.scale);
}

/** Decode a log10-u16 (or u8, float16) buffer of n values. */
export function decodeCodes(buf: ArrayBuffer, enc: string, n: number, log10Min: number, log10Step: number, label = "tile", scale = 1): Float32Array {
  const out = new Float32Array(n);
  if (enc === "log10-u16" || enc === "log10-u8") {
    const codes = enc === "log10-u16" ? new Uint16Array(buf) : new Uint8Array(buf);
    if (codes.length !== n) throw new Error(`${label}: ${codes.length} values, expected ${n}`);
    // A lookup table of the 65,536 possible codes is exact (same expression) and faster.
    const lut = codeTable(log10Min, log10Step, enc === "log10-u16" ? 65536 : 256);
    for (let i = 0; i < n; i++) out[i] = lut[codes[i]];
  } else if (enc === "float16") {
    const h = new Uint16Array(buf);
    for (let i = 0; i < n; i++) out[i] = half(h[i]) * scale;
  } else throw new Error(`unknown encoding ${enc}`);
  return out;
}

function codeTable(a: number, b: number, size: number): Float32Array {
  const t = new Float32Array(size);
  for (let k = 1; k < size; k++) t[k] = Math.pow(10, a + (k - 1) * b);
  return t;
}

function half(h: number): number {
  const s = h & 0x8000 ? -1 : 1, e = (h >> 10) & 0x1f, f = h & 0x3ff;
  if (e === 0) return s * Math.pow(2, -14) * (f / 1024);
  if (e === 31) return f ? NaN : s * Infinity;
  return s * Math.pow(2, e - 15) * (1 + f / 1024);
}

const logOf = (v: number) => (v > 0 ? Math.log(v) : -Infinity);

/** Arrange a decoded field for sampling: polar fields get a periodic phi extension and the ring-0 mean. */
export function prepare(values: Float32Array, grid: GridSpec, entry: Pick<FieldEntry, "frame" | "orientation_deg">): PreparedField {
  const [nz, n1, n2] = grid.shape;
  const z = Float64Array.from(grid.z_m);
  if (entry.frame === "road") {
    const lv = new Float64Array(values.length);
    for (let i = 0; i < values.length; i++) lv[i] = logOf(values[i]);
    return {
      frame: "road", nz, ns: n1, nd: n2, s: Float64Array.from(grid.s_m!), d: Float64Array.from(grid.d_m!), z,
      v: Float32Array.from(values), lv, orientation: entry.orientation_deg || 0,
    };
  }
  const nr = n1, np = n2;
  const r = Float64Array.from(grid.r_m!), phi = Float64Array.from(grid.phi_deg!);
  const npe = np + 2;
  const phiExt = new Float64Array(npe);
  phiExt[0] = phi[np - 1] - 360; phiExt[npe - 1] = phi[0] + 360;
  for (let j = 0; j < np; j++) phiExt[j + 1] = phi[j];
  const v = new Float32Array(nz * nr * npe), lv = new Float64Array(nz * nr * npe);
  for (let iz = 0; iz < nz; iz++) for (let ir = 0; ir < nr; ir++) {
    const src = (iz * nr + ir) * np, dst = (iz * nr + ir) * npe;
    for (let j = 0; j < np; j++) v[dst + j + 1] = values[src + j];
    v[dst] = values[src + np - 1]; v[dst + npe - 1] = values[src];
    for (let j = 0; j < npe; j++) lv[dst + j] = logOf(v[dst + j]);
  }
  const ring0 = new Float64Array(nz);
  for (let iz = 0; iz < nz; iz++) {
    let s = 0;
    for (let j = 0; j < np; j++) s += values[(iz * nr) * np + j] * (phiExt[j + 2] - phiExt[j]) / 720;
    ring0[iz] = s;
  }
  const logr = new Float64Array(nr);
  for (let i = 0; i < nr; i++) logr[i] = Math.log(r[i]);
  return { frame: "polar", nz, nr, np, npe, r, logr, phiExt, z, v, lv, ring0 };
}

/** Approximate memory held by a prepared field (bytes). */
export function preparedBytes(f: PreparedField): number {
  return f.v.byteLength + f.lv.byteLength;
}

const SNAP = 1e-3;
const D2R = Math.PI / 180;

// Scratch outputs of the bracketing helpers.
let bLo = 0, bT = 0;

function bracket(axis: Float64Array, q: number): void {   // lower index (clipped) and unclipped weight
  const n = axis.length;
  let lo = 0, hi = n - 1;
  if (q <= axis[0]) lo = 0;
  else if (q >= axis[hi]) lo = hi - 1;
  else { while (hi - lo > 1) { const m = (lo + hi) >> 1; if (axis[m] <= q) lo = m; else hi = m; } }
  if (lo > n - 2) lo = n - 2;
  bLo = lo; bT = (q - axis[lo]) / (axis[lo + 1] - axis[lo]);
}

function snapBracket(axis: Float64Array, q: number): void { // snapped, clipped weight (road frame and z)
  bracket(axis, q);
  let t = bT;
  if (Math.abs(q - axis[bLo]) < SNAP) t = 0;
  if (Math.abs(q - axis[bLo + 1]) < SNAP) t = 1;
  bT = Math.min(Math.max(t, 0), 1);
}

/**
 * Sample one prepared field (µg/m³ per g/s) at a map point for a source at (xs, ys) and wind FROM
 * wd (degrees). mirror = true reflects the query point across the downwind axis through the source.
 */
export function sample(f: PreparedField, xs: number, ys: number, wd: number, x: number, y: number, zq: number, mirror = false): number {
  let dx = x - xs, dy = y - ys;
  const b = ((wd + 180) % 360) * D2R;
  if (mirror) {
    const al = dx * Math.sin(b) + dy * Math.cos(b), cr = -(dx * Math.cos(b) - dy * Math.sin(b));
    dx = al * Math.sin(b) + cr * Math.cos(b); dy = al * Math.cos(b) - cr * Math.sin(b);
  }
  const z = Math.max(zq, 0);
  if (z > f.z[f.nz - 1] + SNAP) return 0;
  return f.frame === "road" ? sampleRoad(f, dx, dy, wd, z) : samplePolar(f, dx, dy, wd, z);
}

function sampleRoad(f: RoadField, dx: number, dy: number, wd: number, z: number): number {
  const a = (((wd + 180) % 360) + f.orientation) * D2R;
  const s = dx * Math.sin(a) + dy * Math.cos(a), d = dx * Math.cos(a) - dy * Math.sin(a);
  if (s < f.s[0] - SNAP || s > f.s[f.ns - 1] + SNAP || d < f.d[0] - SNAP || d > f.d[f.nd - 1] + SNAP) return 0;
  snapBracket(f.s, Math.min(Math.max(s, f.s[0]), f.s[f.ns - 1])); const is = bLo, ts = bT;
  snapBracket(f.d, Math.min(Math.max(d, f.d[0]), f.d[f.nd - 1])); const id = bLo, td = bT;
  snapBracket(f.z, Math.min(z, f.z[f.nz - 1])); const iz = bLo, tz = bT;
  if ((ts === 0 || ts === 1) && (td === 0 || td === 1) && (tz === 0 || tz === 1))
    return f.v[((iz + tz) * f.ns + (is + ts)) * f.nd + (id + td)];
  let lin = 0, lg = 0, pos = true;
  for (let p = 0; p < 2; p++) for (let q = 0; q < 2; q++) for (let c = 0; c < 2; c++) {
    const w = (p ? tz : 1 - tz) * (q ? ts : 1 - ts) * (c ? td : 1 - td);
    const k = ((iz + p) * f.ns + (is + q)) * f.nd + (id + c);
    lin += w * f.v[k];
    const l = f.lv[k];
    if (l === -Infinity) pos = false; else lg += w * l;
  }
  return pos ? Math.exp(lg) : lin;
}

function samplePolar(f: PolarField, dx: number, dy: number, wd: number, z: number): number {
  const r = Math.hypot(dx, dy);
  let phi = (Math.atan2(dx, dy) / D2R - ((wd + 180) % 360)) % 360;
  if (phi < 0) phi += 360;
  if (phi > 180) phi -= 360;
  const inner = r < f.r[0] - SNAP, beyond = r > f.r[f.nr - 1] + SNAP;
  const rr = Math.max(r, f.r[0]);
  bracket(f.logr, Math.log(rr));
  const ir = bLo; let tr = bT;
  if (Math.abs(rr - f.r[ir]) < SNAP) tr = 0;
  if (Math.abs(rr - f.r[ir + 1]) < SNAP) tr = 1;
  if (inner) tr = 0;
  bracket(f.phiExt, phi);
  const ip = bLo; let tp = bT;
  const arc = D2R * Math.max(rr, f.r[0]);
  if (Math.abs(phi - f.phiExt[ip]) * arc < SNAP) tp = 0;
  if (Math.abs(phi - f.phiExt[ip + 1]) * arc < SNAP) tp = 1;
  tp = Math.min(Math.max(tp, 0), 1);
  snapBracket(f.z, Math.min(z, f.z[f.nz - 1]));
  const iz = bLo, tz = bT;
  const trc = Math.min(Math.max(tr, 0), 1);
  let lin = 0, lIn = 0, lExt = 0, pos = true;
  for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) for (let c = 0; c < 2; c++) {
    const k = ((iz + a) * f.nr + (ir + b)) * f.npe + (ip + c);
    const wz = a ? tz : 1 - tz, wp = c ? tp : 1 - tp;
    const w = wz * (b ? trc : 1 - trc) * wp, we = wz * (b ? tr : 1 - tr) * wp;
    lin += w * f.v[k];
    const l = f.lv[k];
    if (l === -Infinity) pos = false; else { lIn += w * l; lExt += we * l; }
  }
  let out = pos ? Math.exp(beyond ? Math.min(lExt, lIn) : lIn) : lin;
  const node = (tr === 0 || tr === 1) && (tp === 0 || tp === 1) && (tz === 0 || tz === 1) && !inner && !beyond;
  if (node) out = f.v[((iz + tz) * f.nr + (ir + tr)) * f.npe + (ip + tp)];
  if (inner) {
    const cbar = (1 - tz) * f.ring0[iz] + tz * f.ring0[iz + 1], g = r / f.r[0];
    out = g * out + (1 - g) * cbar;
  }
  return out;
}
