// Field worker: holds the fields of the sources routed to it, samples unit maps onto the
// display grid, and samples points (probe, cross-section, linearity points).
/// <reference lib="webworker" />
import { sample, sampleUnitGrid } from "../engine";
import { FieldStore } from "./store";
import { fieldKey, type Reply, type Request } from "./protocol";

let store: FieldStore | null = null;
const post = (r: Reply, transfer: Transferable[] = []) => (self as unknown as DedicatedWorkerGlobalScope).postMessage(r, transfer);

self.onmessage = async (ev: MessageEvent<Request>) => {
  const m = ev.data;
  if (m.type === "init") { store = new FieldStore(m.base, m.grids, m.encoding, m.fields); return; }
  const id = m.id;
  try {
    if (!store) throw new Error("worker not initialised");
    const t0 = performance.now();
    if (m.type === "prefetch") {
      for (const k of m.keys) { if (m.prepare) await store.get(k); else await store.fetchRaw(k); }
      post({ id, ok: true, ms: performance.now() - t0 });
    } else if (m.type === "unitMap") {
      const f = await store.get(fieldKey(m.sourceId, m.scenarioId));
      const t1 = performance.now();
      const map = sampleUnitGrid(f, m.x, m.y, m.wd, m.grid, m.z);
      post({ id, ok: true, map, ms: performance.now() - t0, loadMs: t1 - t0 }, [map.buffer]);
    } else if (m.type === "points") {
      const values: Float64Array[] = [];
      for (const it of m.items) {
        const f = await store.get(fieldKey(it.sourceId, m.scenarioId));
        const v = new Float64Array(m.xs.length);
        for (let k = 0; k < v.length; k++) v[k] = sample(f, it.x, it.y, m.wd, m.xs[k], m.ys[k], m.zs[k], !!it.mirror);
        values.push(v);
      }
      post({ id, ok: true, values, ms: performance.now() - t0 }, values.map((v) => v.buffer));
    }
  } catch (e) {
    post({ id, ok: false, error: String((e as Error)?.message || e) });
  }
};
