// Linear superposition of scaled unit fields, plus the display-grid helpers. No DOM access.
//
//   C(x, y, z) = background + sum_i rate_i (1 - efficiency_i) F_i(x - x_i, y - y_i, z; wd)
//                + traffic_scale * sum_{enabled tiers} road_baseline_tier(x, y)
//
// mirrors aqsim.engine.superpose_fields; the road term is the precomputed road baseline (C).
import type { Placement } from "../types";
import { sample, type PreparedField } from "./field";

/** Effective emission (g/s): rate x (1 - efficiency). Efficiency must lie in [0, 1]. */
export function effectiveRate(rate: number, efficiency = 0): number {
  if (!(rate >= 0)) throw new Error(`negative or invalid emission rate ${rate}`);
  if (!(efficiency >= 0 && efficiency <= 1)) throw new Error(`control efficiency must be in [0, 1], got ${efficiency}`);
  return rate * (1 - efficiency);
}

/** Pure core, as aqsim.engine.superpose_fields: plume sum at the query points plus a constant background. */
export function superposeFields(
  placements: readonly Placement[], fields: Record<string, PreparedField> | Map<string, PreparedField>,
  windFromDeg: number, xq: ArrayLike<number>, yq: ArrayLike<number>, zq: ArrayLike<number>, background = 0,
): Float64Array {
  const n = xq.length;
  if (yq.length !== n || zq.length !== n) throw new Error("xq, yq and zq must have the same length");
  const get = (id: string) => (fields instanceof Map ? fields.get(id) : fields[id]);
  const total = new Float64Array(n);
  for (const p of placements) {
    const q = effectiveRate(p.rate_g_s, p.control_efficiency ?? 0);
    if (q === 0) continue;
    const f = get(p.source_id);
    if (!f) throw new Error(`no unit field for source_id ${p.source_id}`);
    const m = !!p.mirror;
    for (let k = 0; k < n; k++) total[k] += q * sample(f, p.x, p.y, windFromDeg, xq[k], yq[k], zq[k], m);
  }
  if (background) for (let k = 0; k < n; k++) total[k] += background;
  return total;
}

/** The 100 m display grid over the 30 km domain. Cell (i, j) centre = (x0 + d/2 + d i, y0 + d/2 + d j); index j * nx + i (j = 0 in the south). */
export interface DisplayGrid { nx: number; ny: number; x0: number; y0: number; d: number }

export function cellCentreX(g: DisplayGrid, i: number): number { return g.x0 + g.d / 2 + g.d * i; }
export function cellCentreY(g: DisplayGrid, j: number): number { return g.y0 + g.d / 2 + g.d * j; }

/** Unit map (per g/s) of one field on the display grid at height z. */
export function sampleUnitGrid(f: PreparedField, xs: number, ys: number, wd: number, g: DisplayGrid, z = 0, mirror = false, out?: Float32Array): Float32Array {
  const res = out ?? new Float32Array(g.nx * g.ny);
  for (let j = 0; j < g.ny; j++) {
    const y = g.y0 + g.d / 2 + g.d * j;
    for (let i = 0; i < g.nx; i++) res[j * g.nx + i] = sample(f, xs, ys, wd, g.x0 + g.d / 2 + g.d * i, y, z, mirror);
  }
  return res;
}

export interface ScaledMap { map: Float32Array; scale: number }

export interface Combined {
  increment: Float32Array;   // placed sources + roads (µg/m³)
  background: number;        // added once
  max: number;               // highest total (background + increment)
  maxIdx: number;
  incMax: number;
}

/**
 * Scaled sum of cached unit maps and road maps, with the background added once. This is the
 * hot path for rate, control, tier and traffic changes (no resampling).
 */
export function combineMaps(sources: readonly ScaledMap[], roads: readonly ScaledMap[], background: number, n: number, out?: Float32Array): Combined {
  const inc = out && out.length === n ? out : new Float32Array(n);
  inc.fill(0);
  for (const s of [...sources, ...roads]) {
    if (!s.scale) continue;
    const m = s.map, q = s.scale;
    for (let k = 0; k < n; k++) inc[k] += q * m[k];
  }
  let incMax = 0, maxIdx = 0;
  for (let k = 0; k < n; k++) if (inc[k] > incMax) { incMax = inc[k]; maxIdx = k; }
  return { increment: inc, background, max: background + incMax, maxIdx, incMax };
}
