// Messages between the main thread and the field workers.
import type { FieldEntry, GridSpec } from "../engine/manifest";
import type { DisplayGrid } from "../engine/superpose";

export interface InitMsg { type: "init"; base: string; grids: Record<string, GridSpec>; encoding: { name: string }; fields: FieldEntry[] }
export interface PrefetchMsg { type: "prefetch"; id: number; keys: string[]; prepare: boolean }
export interface UnitMapMsg { type: "unitMap"; id: number; sourceId: string; scenarioId: string; x: number; y: number; wd: number; grid: DisplayGrid; z: number }
export interface PointsMsg {
  type: "points"; id: number; scenarioId: string; wd: number;
  items: { sourceId: string; x: number; y: number; mirror?: boolean }[];
  xs: Float64Array; ys: Float64Array; zs: Float64Array;
}
export type Request = InitMsg | PrefetchMsg | UnitMapMsg | PointsMsg;

export interface Reply {
  id: number;
  ok: boolean;
  error?: string;
  map?: Float32Array;
  values?: Float64Array[];          // one array per item (points)
  ms?: number;                      // worker-side compute time
  loadMs?: number;                  // fetch + decode + prepare time included in ms
}

export const fieldKey = (sourceId: string, scenarioId: string) => `${sourceId}__${scenarioId}`;
